 * The two policy kinds a route can chain: token buckets and sliding windows.
 * Each keeps one independent state per key, created lazily the first time
 * that key reaches the policy.
 */

/**
 * A token bucket. Tokens are tracked as an integer count of `1/per`ths of a
 * token, so refilling by `refill` tokens per `per` ticks over any number of
 * elapsed ticks is exact integer arithmetic with no rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.states = new Map()
  }

  #state(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { units: this.max, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(tick, key) {
    const state = this.#state(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.units += this.refill * elapsed
      if (state.units > this.max) state.units = this.max
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).units >= this.per
  }

  record(key) {
    this.states.get(key).units -= this.per
  }
}

