  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

