import { LineError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

function parseUint(token, field, least, lineNumber) {
  if (!UINT_RE.test(token)) {
    throw new LineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(token)
  if (value < BigInt(least)) {
    throw new LineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  return value
}

function checkToken(token, kind, lineNumber) {
  if (!TOKEN_RE.test(token)) {
    throw new LineError(lineNumber, `invalid ${kind} ${token}`)
  }
}

/**
 * Replays a limiter file, one line at a time, and reports the verdict of
 * every event through `onEvent`.
 */
export class Engine {
  constructor() {
    this.policies = new Map()
    this.routes = new Map()
    this.seenEvent = false
    this.lastTick = null
  }

  #requireDeclarationPhase(lineNumber) {
    if (this.seenEvent) {
      throw new LineError(lineNumber, 'declarations must come before the first event')
    }
  }

  #declareBucket(tokens, lineNumber) {
    if (tokens.length !== 5) {
      throw new LineError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
    }
    this.#requireDeclarationPhase(lineNumber)
    const [, name, capacityTok, refillTok, perTok] = tokens
    checkToken(name, 'policy name', lineNumber)
    const capacity = parseUint(capacityTok, 'capacity', 1, lineNumber)
    const refill = parseUint(refillTok, 'refill', 0, lineNumber)
    const per = parseUint(perTok, 'per', 1, lineNumber)
    if (this.policies.has(name)) {
      throw new LineError(lineNumber, `policy ${name} is declared twice`)
    }
    this.policies.set(name, new TokenBucket(capacity, refill, per))
  }

  #declareWindow(tokens, lineNumber) {
    if (tokens.length !== 4) {
      throw new LineError(lineNumber, 'expected window <name> <limit> <span>')
    }
    this.#requireDeclarationPhase(lineNumber)
    const [, name, limitTok, spanTok] = tokens
    checkToken(name, 'policy name', lineNumber)
    const limit = parseUint(limitTok, 'limit', 0, lineNumber)
    const span = parseUint(spanTok, 'span', 1, lineNumber)
    if (this.policies.has(name)) {
      throw new LineError(lineNumber, `policy ${name} is declared twice`)
    }
    this.policies.set(name, new SlidingWindow(limit, span))
  }

  #declareRoute(tokens, lineNumber) {
    if (tokens.length < 3) {
      throw new LineError(lineNumber, 'expected route <prefix> <policy>...')
    }
    this.#requireDeclarationPhase(lineNumber)
    const prefix = tokens[1]
    const policyNames = tokens.slice(2)
    checkToken(prefix, 'route prefix', lineNumber)
    for (const name of policyNames) {
      if (!this.policies.has(name)) {
        throw new LineError(lineNumber, `unknown policy ${name}`)
      }
    }
    if (this.routes.has(prefix)) {
      throw new LineError(lineNumber, `prefix ${prefix} is routed twice`)
    }
    this.routes.set(prefix, policyNames)
  }

  #findRoute(key) {
    let best = null
    for (const prefix of this.routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) {
        best = prefix
      }
    }
    return best
  }

  #handleEvent(tokens, lineNumber, onEvent) {
    if (tokens.length !== 3) {
      throw new LineError(lineNumber, 'expected event <tick> <key>')
    }
    const [, tickTok, key] = tokens
    const tick = parseUint(tickTok, 'tick', 0, lineNumber)
    checkToken(key, 'key', lineNumber)
    if (this.lastTick !== null && tick < this.lastTick) {
      throw new LineError(lineNumber, `tick ${tick} is before tick ${this.lastTick}`)
    }
    this.lastTick = tick
    this.seenEvent = true

    const prefix = this.#findRoute(key)
    let denyPolicy = null
    if (prefix !== null) {
      const names = this.routes.get(prefix)
      const policies = names.map((name) => this.policies.get(name))
      for (const policy of policies) policy.advance(tick, key)
      for (let i = 0; i < policies.length; i++) {
        if (!policies[i].allow(key)) {
          denyPolicy = names[i]
          break
        }
      }
      if (denyPolicy === null) {
        for (const policy of policies) policy.record(key, tick)
      }
    }
    onEvent(tick, key, denyPolicy === null, denyPolicy)
  }

  /**
   * Applies one already-trimmed, non-empty, non-comment line. `onEvent` is
   * called for every `event` line with `(tick, key, allowed, denyPolicy)`.
   */
  applyLine(tokens, lineNumber, onEvent) {
    switch (tokens[0]) {
      case 'bucket':
        return this.#declareBucket(tokens, lineNumber)
      case 'window':
        return this.#declareWindow(tokens, lineNumber)
      case 'route':
        return this.#declareRoute(tokens, lineNumber)
      case 'event':
        return this.#handleEvent(tokens, lineNumber, onEvent)
      default:
        throw new LineError(lineNumber, `unknown directive ${tokens[0]}`)
    }
  }
}
"}

