  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }

  const lines = readLines()
  const engine = new Engine()
  const output = []
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  const onEvent = (tick, key, allowed, denyPolicy) => {
    if (mode === 'replay') {
      output.push(allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${denyPolicy}`)
    } else {
      let counts = perKey.get(key)
      if (!counts) {
        counts = { allowed: 0, denied: 0 }
        perKey.set(key, counts)
      }
      if (allowed) {
        counts.allowed++
        totalAllowed++
      } else {
        counts.denied++
        totalDenied++
      }
    }
  }

  try {
    lines.forEach((rawLine, index) => {
      const line = rawLine.trim()
      if (line === '' || line.startsWith('#')) return
      const tokens = line.split(/\s+/)
      engine.applyLine(tokens, index + 1, onEvent)
    })
  } catch (error) {
    if (error instanceof LineError) {
      fail(`line ${error.lineNumber}: ${error.message}`)
    }
    throw error
  }

  if (mode === 'replay') {
    for (const line of output) process.stdout.write(`${line}\n`)
  } else {
    const keys = [...perKey.keys()].sort()
    for (const key of keys) {
      const counts = perKey.get(key)
      process.stdout.write(`${key} allowed=${counts.allowed} denied=${counts.denied}\n`)
    }
    process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  }
  process.exit(0)
}

main()
"}

